import{_ as n,C as s,c as l,o as f,ag as a,j as e,G as r,a as i}from"./chunks/framework.Bw-5EFTY.js";const S=JSON.parse('{"title":"LifterLMS Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/lifterlms-integration-with-fluentaffiliate.md","filePath":"guide/integrations/lifterlms-integration-with-fluentaffiliate.md","lastUpdated":1755603747000}'),u={name:"guide/integrations/lifterlms-integration-with-fluentaffiliate.md"};function g(c,t,h,d,m,p){const o=s("ZoomableImage");return f(),l("div",null,[t[0]||(t[0]=a('<h1 id="lifterlms-integration-with-fluentaffiliate" tabindex="-1">LifterLMS Integration with FluentAffiliate <a class="header-anchor" href="#lifterlms-integration-with-fluentaffiliate" aria-label="Permalink to &quot;LifterLMS Integration with FluentAffiliate&quot;">​</a></h1><p>Want to grow your online course sales through affiliate marketing? With FluentAffiliate, you can now easily integrate with LifterLMS and start tracking affiliate referrals for your courses. This guide will show you how to set it up in just a few clicks!</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lifterlms is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>Make sure both the LifterLMS and FluentAffiliate plugins are installed and activated on your site before you begin.</p></div><h2 id="enable-the-lifterlms-integration" tabindex="-1">Enable the LifterLMS Integration <a class="header-anchor" href="#enable-the-lifterlms-integration" aria-label="Permalink to &quot;Enable the LifterLMS Integration&quot;">​</a></h2><p>First, you need to activate the LifterLMS module within FluentAffiliate to allow them to communicate.</p><ol><li>Go to your <strong>WordPress Dashboard</strong>, navigate to <strong>FluentAffiliate Dashboards</strong>, and click on the <strong>Settings</strong> tab top right corner.</li><li>Then, click on <strong>Integration Settings</strong> from the left sidebar.</li><li>Find <strong>LifterLMS</strong> in the list and click the <strong>toggle</strong> button to switch it on. A <strong>Manage</strong> link will appear.</li></ol>',6)),e("p",null,[r(o,{src:"/guide/public/images/integrations/lifterlms/integration-setup-options.webp",alt:"Integration Settings"})]),t[1]||(t[1]=e("h3",{id:"configure-lifterlms-settings",tabindex:"-1"},[i("Configure LifterLMS Settings "),e("a",{class:"header-anchor",href:"#configure-lifterlms-settings","aria-label":'Permalink to "Configure LifterLMS Settings"'},"​")],-1)),t[2]||(t[2]=e("p",null,[i("Click the "),e("strong",null,"Manage"),i(" link to open the settings panel. Here, you can set custom commission rates for your LifterLMS courses, which will override your global affiliate settings.")],-1)),t[3]||(t[3]=e("ul",null,[e("li",null,[e("strong",null,"Enable Affiliate Integration for LifterLMS:"),i(" You must check this box to activate commission tracking for all your LifterLMS courses.")]),e("li",null,[e("strong",null,"Enable custom rate for specific courses or Course Categories:"),i(" Check this box if you want to offer different commission rates for different courses. This is perfect for running special promotions or offering a higher incentive for your signature courses.")])],-1)),e("p",null,[r(o,{src:"/guide/public/images/integrations/lifterlms/lifterlms-settings-configuration.webp",alt:"LifterLMS Settings"})]),t[4]||(t[4]=a('<h3 id="custom-affiliate-rate-configuration" tabindex="-1">Custom Affiliate Rate Configuration <a class="header-anchor" href="#custom-affiliate-rate-configuration" aria-label="Permalink to &quot;Custom Affiliate Rate Configuration&quot;">​</a></h3><p>Once you enable custom rates, you can define your specific commission rules.</p><p>First, you must choose if the custom rate will apply <strong>By Specific Products</strong> (which refers to your individual LifterLMS courses) or <strong>By Specific Categories</strong>.</p><p>Next, configure the rate itself:</p><ol><li><p><strong>Select Courses:</strong> In the Select field, start typing the name of the course you want to set a custom rate for and choose it from the list.</p></li><li><p><strong>Select Rate:</strong> Enter the commission value (e.g., 25 for 25% or $25) and use the dropdown menu to choose if the rate is a Percentage (%) or a Fixed amount.</p></li><li><p><strong>Add More Rates:</strong> If you want to set another custom rate for a different course, click the <strong>+Add New Group</strong> button. This adds a new row for you to create another rule. You can also remove a rule by clicking the red <strong>Delete</strong> icon.</p></li><li><p><strong>Save Settings:</strong> After configuring your custom rates, click the <strong>Save Settings</strong> button to make them live.</p></li></ol>',5)),e("p",null,[r(o,{src:"/guide/public/images/integrations/lifterlms/configure-custom-affiliate-rate.webp",alt:"Custom Affiliate Rate Configuration"})]),t[5]||(t[5]=a('<h3 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h3><p>Now that the integration is set up, your affiliates can start promoting your Courses. To do this, they need to generate your <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a> from their affiliate dashboard.</p><p>When a student clicks the link and enrolls in the course, the affiliate earns a commission based on the rates you&#39;ve set!</p><h3 id="troubleshooting-tips" tabindex="-1">Troubleshooting Tips <a class="header-anchor" href="#troubleshooting-tips" aria-label="Permalink to &quot;Troubleshooting Tips&quot;">​</a></h3><ul><li><p><strong>Affiliate Sale Not Tracked:</strong> Verify that the integration toggle is enabled in FluentAffiliate&#39;s settings. If you&#39;re using custom rates, double-check that they are configured correctly for the specific course being purchased.</p></li><li><p><strong>Affiliate Not Getting Credit:</strong> This can sometimes be a browser issue on the customer&#39;s end. Ensure they don&#39;t have cookies blocked and that they completed the checkout without clearing their session or switching browsers.</p></li></ul>',5))])}const y=n(u,[["render",g]]);export{S as __pageData,y as default};
